import React from 'react';
import { useCompare } from '../context/CompareContext';
import { useTheme } from '../context/ThemeContext';

const CompareModal = ({ isOpen, onClose }) => {
  const { compareProducts, removeFromCompare, clearCompare } = useCompare();
  const { isDarkMode } = useTheme;

  if (!isOpen || compareProducts.length === 0) return null;

  const features = [
    { key: 'price', label: 'Price', format: (val) => `₹${val}` },
    { key: 'category', label: 'Category', format: (val) => val },
    { key: 'unit', label: 'Unit', format: (val) => val || 'L' },
    { key: 'stock', label: 'Stock', format: (val) => val ? 'In Stock' : 'Out of Stock' },
  ];

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4" style={{ background: 'rgba(0,0,0,0.6)', backdropFilter: 'blur(8px)' }}>
      <div className="w-full max-w-6xl max-h-[90vh] overflow-hidden rounded-2xl border-2 animate-in fade-in zoom-in-95 duration-300"
           style={{ 
             background: isDarkMode ? 'rgba(17, 24, 39, 0.95)' : 'rgba(255, 255, 255, 0.95)',
             backdropFilter: 'blur(24px)',
             borderColor: isDarkMode ? 'rgba(139, 92, 246, 0.5)' : 'rgba(139, 92, 246, 0.4)',
             boxShadow: '0 25px 50px -12px rgba(139, 92, 246, 0.25)'
           }}>
        {/* Header */}
        <div className="p-6 border-b" style={{ borderColor: isDarkMode ? 'rgba(139, 92, 246, 0.3)' : 'rgba(139, 92, 246, 0.2)' }}>
          <div className="flex items-center justify-between">
            <h2 className="text-2xl font-bold flex items-center gap-2" style={{ color: isDarkMode ? '#fff' : '#1f2937' }}>
              <svg className="w-6 h-6 text-purple-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
              </svg>
              Compare Products
            </h2>
            <button
              onClick={onClose}
              className={`p-2 rounded-xl transition-all hover:scale-110 ${isDarkMode ? 'hover:bg-white/10 text-gray-400' : 'hover:bg-gray-100 text-gray-600'}`}
            >
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>
        </div>

        {/* Content */}
        <div className="p-6 overflow-y-auto max-h-[calc(90vh-140px)]">
          <div className="grid gap-6" style={{ gridTemplateColumns: `repeat(${compareProducts.length + 1}, minmax(200px, 1fr))` }}>
            {/* Feature Labels Column */}
            <div className="space-y-4">
              <div className="h-32"></div>
              {features.map((feature, idx) => (
                <div key={idx} className="p-3 rounded-xl" style={{ 
                  background: isDarkMode ? 'rgba(139, 92, 246, 0.1)' : 'rgba(139, 92, 246, 0.05)',
                  color: isDarkMode ? '#c4b5fd' : '#7c3aed',
                  fontWeight: '600'
                }}>
                  {feature.label}
                </div>
              ))}
              <div className="p-3 rounded-xl font-semibold" style={{ 
                background: isDarkMode ? 'rgba(139, 92, 246, 0.1)' : 'rgba(139, 92, 246, 0.05)',
                color: isDarkMode ? '#c4b5fd' : '#7c3aed'
              }}>
                Actions
              </div>
            </div>

            {/* Product Columns */}
            {compareProducts.map((product) => (
              <div key={product._id} className="space-y-4">
                {/* Product Image */}
                <div className="h-32 rounded-xl flex items-center justify-center" style={{ background: isDarkMode ? 'rgba(31, 41, 55, 0.5)' : 'rgba(249, 250, 251, 0.5)' }}>
                  {product.image ? (
                    <img src={product.image} alt={product.name} className="w-full h-full object-cover rounded-xl" />
                  ) : (
                    <span className="text-4xl">🥛</span>
                  )}
                </div>

                {/* Product Name */}
                <div className="p-3 rounded-xl" style={{ background: isDarkMode ? 'rgba(31, 41, 55, 0.3)' : 'rgba(249, 250, 251, 0.3)' }}>
                  <p className="font-semibold text-sm" style={{ color: isDarkMode ? '#fff' : '#1f2937' }}>{product.name}</p>
                </div>

                {/* Features */}
                {features.map((feature, idx) => (
                  <div key={idx} className="p-3 rounded-xl text-center" style={{ 
                    background: isDarkMode ? 'rgba(31, 41, 55, 0.3)' : 'rgba(249, 250, 251, 0.3)',
                    color: isDarkMode ? '#d1d5db' : '#4b5563'
                  }}>
                    {feature.format(product[feature.key] || '-')}
                  </div>
                ))}

                {/* Actions */}
                <div className="p-3 rounded-xl flex gap-2" style={{ background: isDarkMode ? 'rgba(31, 41, 55, 0.3)' : 'rgba(249, 250, 251, 0.3)' }}>
                  <button
                    onClick={() => removeFromCompare(product._id)}
                    className="flex-1 py-2 rounded-xl text-xs font-semibold transition-all hover:scale-105"
                    style={{ 
                      background: isDarkMode ? 'rgba(239, 68, 68, 0.2)' : 'rgba(239, 68, 68, 0.1)',
                      color: isDarkMode ? '#f87171' : '#ef4444',
                      border: isDarkMode ? '1px solid rgba(239, 68, 68, 0.3)' : '1px solid rgba(239, 68, 68, 0.2)'
                    }}
                  >
                    Remove
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Footer */}
        <div className="p-6 border-t flex items-center justify-between" style={{ borderColor: isDarkMode ? 'rgba(139, 92, 246, 0.3)' : 'rgba(139, 92, 246, 0.2)' }}>
          <button
            onClick={clearCompare}
            className="px-4 py-2 rounded-xl font-semibold transition-all hover:scale-105"
            style={{ 
              background: isDarkMode ? 'rgba(239, 68, 68, 0.2)' : 'rgba(239, 68, 68, 0.1)',
              color: isDarkMode ? '#f87171' : '#ef4444',
              border: isDarkMode ? '1px solid rgba(239, 68, 68, 0.3)' : '1px solid rgba(239, 68, 68, 0.2)'
            }}
          >
            Clear All
          </button>
          <button
            onClick={onClose}
            className="px-6 py-2 rounded-xl font-semibold text-white transition-all hover:scale-105"
            style={{ 
              background: 'linear-gradient(135deg, #8b5cf6 0%, #ec4899 100%)',
              boxShadow: '0 4px 15px rgba(139, 92, 246, 0.3)'
            }}
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
};

export default CompareModal;
